SELECT 'Index' Kind, t.name TableName,i.name ObjectName,
CONCAT(i.is_unique,'|',i.is_primary_key,'|',i.type_desc COLLATE DATABASE_DEFAULT,'|',COALESCE(i.filter_definition COLLATE DATABASE_DEFAULT,''),'|',STRING_AGG(CONVERT(nvarchar(max),CONCAT(c.name COLLATE DATABASE_DEFAULT,':',ic.key_ordinal,':',ic.is_descending_key,':',ic.is_included_column)),',') WITHIN GROUP(ORDER BY ic.index_column_id)) Definition
FROM sys.tables t JOIN sys.indexes i ON i.object_id=t.object_id JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.index_id>0 AND i.is_disabled=0 GROUP BY t.name,i.name,i.is_unique,i.is_primary_key,i.type_desc,i.filter_definition
UNION ALL SELECT 'Check',OBJECT_NAME(parent_object_id),name,definition FROM sys.check_constraints WHERE is_disabled=0 AND is_not_trusted=0
UNION ALL SELECT 'ForeignKey',OBJECT_NAME(f.parent_object_id),f.name,CONCAT(OBJECT_NAME(f.referenced_object_id),'|',f.delete_referential_action_desc COLLATE DATABASE_DEFAULT,'|',f.update_referential_action_desc COLLATE DATABASE_DEFAULT,'|',STRING_AGG(CONVERT(nvarchar(max),CONCAT(COL_NAME(k.parent_object_id,k.parent_column_id),'=',COL_NAME(k.referenced_object_id,k.referenced_column_id))),',') WITHIN GROUP(ORDER BY k.constraint_column_id)) FROM sys.foreign_keys f JOIN sys.foreign_key_columns k ON k.constraint_object_id=f.object_id WHERE f.is_disabled=0 AND f.is_not_trusted=0 GROUP BY f.parent_object_id,f.name,f.referenced_object_id,f.delete_referential_action_desc,f.update_referential_action_desc
UNION ALL SELECT 'Module',COALESCE(OBJECT_NAME(t.parent_id),''),o.name,m.definition FROM sys.objects o JOIN sys.sql_modules m ON m.object_id=o.object_id LEFT JOIN sys.triggers t ON t.object_id=o.object_id WHERE o.type='FN' OR (o.type='TR' AND t.is_disabled=0 AND t.is_ms_shipped=0)
ORDER BY Kind,TableName,ObjectName
